WITH exploded AS (SELECT id, service, host, log_ts, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS attr_key, v) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, DATE_TRUNC('HOUR', log_ts) AS hour_window, ROUND(SUM(status_code) / NULLIF(COUNT(CASE WHEN attr_key = 'version' THEN 1 END), 0), 2) AS status_code_per_version, MIN(log_ts) AS first_log_ts FROM exploded GROUP BY DATE_TRUNC('DAY', log_ts), DATE_TRUNC('HOUR', log_ts) ORDER BY activity_day DESC
